public partial class GameForm {
 Franchise franchise;int selectedPlayer=-1,tradePlayer=-1,tradePartner=-1,viewTeam,matchFixture=-1,brandMascot,brandPrimary,brandSecondary;
 string confirmTitle="",confirmDetail="",confirmBack="club";Action confirmAction;
 static readonly string[] OfficeTitlesLegacy={"VIEW ROSTER","TRADE PLAYERS","SIGN PLAYERS","SIGN COACHES","MOVE TEAM","EDIT TEAM","STANDINGS","PLAYOFF PICTURE","SEASON SCHEDULE","TRAINING","FACILITIES","CHOOSE YOUR CLUB","LEAGUE NEWS","INJURY REPORT","BACK TO HOME"};
 static readonly string[] OfficeTitles={"ROSTER","TRADE","SIGN PLAYERS","COACHES","MOVE TEAM","EDIT TEAM","STANDINGS","PLAYOFFS","SCHEDULE","TRAINING","FACILITIES","COACHING JOBS","NEWS","INJURIES","BACK","MY COACH","TROPHIES","HISTORY","CHAMPIONS","STAT LEADERS","STADIUM + MONEY","DRAFT"};
 bool IsFront(){return screen=="draft"||screen=="stadium"||screen=="club"||screen=="confirm"||screen=="roster"||screen=="player"||screen=="lineup"||screen=="freeagents"||screen=="trade"||screen=="partners"||screen=="offers"||screen=="coaches"||screen=="relocate"||screen=="brand"||screen=="standings"||screen=="playoffs"||screen=="schedule"||screen=="training"||screen=="facilities"||screen=="league"||screen=="news"||screen=="injuries"||screen=="teamroster";}
 LeagueTeam VisualClub {get{return (screen=="game"||screen=="calls"||screen=="pause"||screen=="designer"||screen=="emergencyqb")&&game.Franchise!=null?game.Franchise.Teams[game.Franchise.UserTeam]:franchise.Club;}}Color TeamPrimary {get{return Color.FromArgb(255,Color.FromArgb(Franchise.Palette[VisualClub.Primary]));}}
 Color TeamSecondary {get{return Color.FromArgb(255,Color.FromArgb(Franchise.Palette[VisualClub.Secondary]));}}
 ClubPlayer SelectedPlayer {get{return franchise.Players.Find(p=>p.Id==selectedPlayer);}}
 List<ClubPlayer> FrontPlayers(){if(screen=="teamroster")return franchise.Squad(viewTeam);if(screen=="freeagents")return franchise.FreeAgents();if(screen=="offers"){ClubPlayer outgoing=franchise.Players.Find(p=>p.Id==tradePlayer);return franchise.Players.FindAll(p=>p.Team==tradePartner&&outgoing!=null);}List<ClubPlayer> a=franchise.Squad(franchise.UserTeam);a.Sort((x,y)=>{int v=(x.Slot<0?99:x.Slot).CompareTo(y.Slot<0?99:y.Slot);return v!=0?v:y.OVR.CompareTo(x.OVR);});return a;}
 void Confirm(string title,string detail,string back,Action action){CaptureConfirmPlayers(detail);confirmTitle=title;confirmDetail=detail;confirmBack=back;confirmAction=action;Open("confirm");}
 void FrontBack(){if(screen=="confirm"){Open(confirmBack);return;}if(screen=="teamroster")Open("standings");else if(screen=="player"||screen=="partners")Open("roster");else if(screen=="lineup")Open("player");else if(screen=="offers")Open("partners");else if(screen=="club")Open("franchisehub");else Open(MenuParent(screen));}
 List<string> FrontRows(){List<string> a=new List<string>();if(screen=="club")return new List<string>(NewRows());if(screen=="stadium")return new List<string>{"FOOD - $1","FOOD + $1","PARKING - $2","PARKING + $2","BACK TO OFFICE"};
  if(screen=="draft"){if(franchise.DraftActive){foreach(ClubPlayer p in franchise.Prospects)a.Add(p.Line);a.Add("AUTO DRAFT");}a.Add("BACK");return a;}if(screen=="confirm"){a.Add("CANCEL / KEEP CURRENT SETTINGS");a.Add("CONFIRM "+confirmTitle);return a;}
  if(screen=="roster"||screen=="trade"||screen=="freeagents"||screen=="offers"||screen=="teamroster"){foreach(ClubPlayer p in FrontPlayers())a.Add((p.InjuryWeeks>0?"! ":"")+"#"+p.Number+" "+p.Role.PadRight(3)+" "+p.Name.PadRight(11)+" "+p.OVR+" OVR"+(screen=="freeagents"?" / "+p.SigningCost+" CR":""));}
  else if(screen=="player"){ClubPlayer p=SelectedPlayer;if(p!=null){a.Add("SET STARTING POSITION");a.Add("RENEW CONTRACT / "+(3+(p.OVR-70)/3)+" CR");a.Add("RELEASE / FREE "+p.Salary+" CAP");a.Add("FIND A TRADE");}}
  else if(screen=="lineup"){ClubPlayer p=SelectedPlayer;if(p!=null)foreach(int slot in franchise.EligibleSlots(p)){ClubPlayer current=franchise.Starter(franchise.UserTeam,slot);a.Add("SLOT "+(slot+1)+" / "+(current==null?"VACANT":current.Name+" "+current.OVR));}}
  else if(screen=="partners"||screen=="league"){foreach(LeagueTeam t in franchise.Teams)if(screen=="league"||t.Id!=franchise.UserTeam)a.Add(t.Name+(t.Id==franchise.UserTeam?" / YOUR CLUB":franchise.Fired?(franchise.JobAvailable(t.Id)?" / HIRING":" / NO OPENING"):""));}
  else if(screen=="coaches"){string[] names={"OFFENSE / REID","DEFENSE / CARTER","FITNESS / MORGAN"};for(int i=0;i<9;i++)a.Add(names[i/3]+" T"+(i%3+1)+" / "+(10+(i%3)*5)+" CR");}
  else if(screen=="relocate"){foreach(string city in Franchise.Cities)a.Add(city+" / "+(city==franchise.Club.City?"CURRENT CITY":franchise.Teams.Exists(t=>t.City==city)?"OCCUPIED":"15 CR"));a.Add("TYPE A CUSTOM CITY / $45M");}
  else if(screen=="brand"){a.Add("MASCOT / "+Franchise.Mascots[brandMascot]);a.Add("PRIMARY / "+Franchise.Colors[brandPrimary]);a.Add("SECONDARY / "+Franchise.Colors[brandSecondary]);a.Add("SAVE TEAM BRAND / FREE");}
  else if(screen=="standings"){int rank=0;foreach(Standing s in franchise.Table()){rank++;a.Add(rank.ToString("00")+" "+franchise.Teams[s.Team].Mascot.PadRight(12)+" "+s.W+"-"+s.L+"-"+s.T+" / "+s.Diff.ToString("+0;-0;0"));}}
  else if(screen=="schedule"){foreach(Fixture g in franchise.Games)if(g.Involves(franchise.UserTeam))a.Add((g.Round<11?"W"+(g.Round+1):g.Round==11?"WC":g.Round==12?"SF":"FINAL")+" "+(g.Home==franchise.UserTeam?"VS ":"AT ")+franchise.Teams[g.Opponent(franchise.UserTeam)].Mascot+(g.Played?" / "+(g.Home==franchise.UserTeam?g.HomeScore:g.AwayScore)+"-"+(g.Home==franchise.UserTeam?g.AwayScore:g.HomeScore):" / UPCOMING"));a.Add(franchise.DraftActive?"ENTER DRAFT":franchise.Complete?"BEGIN NEXT SEASON":franchise.UserGame==null?"ADVANCE LEAGUE / SIMULATE ROUND":"PLAY SCHEDULED GAME");a.Add("SIM NEXT GAME / USE TEAM RATINGS");}
  else if(screen=="training"){a.Add("PASSING GROUP / 3 CR");a.Add("RUNNING GROUP / 3 CR");a.Add("DEFENSIVE GROUP / 3 CR");}
  else if(screen=="facilities"){int[] lv={franchise.Passing,franchise.Running,franchise.Defense};string[] n={"PASSING LAB","WEIGHT ROOM","DEFENSE FILM ROOM"};for(int i=0;i<3;i++)a.Add(n[i]+" / LV "+lv[i]+(lv[i]>=5?" MAX":" / "+(4+lv[i]*3)+" CR"));}
  else if(screen=="playoffs"){a.Add(franchise.Seeds.Count==0?"PROJECTED BRACKET / NOT YET CLINCHED":"OFFICIAL SIX-TEAM BRACKET");a.Add(franchise.UserGame==null?"ADVANCE LEAGUE ROUND":"PLAY YOUR NEXT GAME");}
  else if(screen=="injuries"){foreach(ClubPlayer p in franchise.Squad(franchise.UserTeam))if(p.InjuryWeeks>0)a.Add(p.Name+" / "+p.Role+" / OUT "+p.InjuryWeeks+" W / "+p.InjuryType);if(a.Count==0)a.Add("EVERYONE IS HEALTHY");}else if(screen=="news"){a.AddRange(franchise.News);if(a.Count==0)a.Add("YOUR STORY STARTS HERE.");}
  if(screen=="roster")a.Add("INJURY REPORT");a.Add("BACK");for(int row=0;row<a.Count;row++)a[row]=MoneyText(a[row]);return a;
 }
 void ActivateFront(){List<string> rows=FrontRows();if(selection<0||selection>=rows.Count)return;
  if(screen=="club"){string[] destinations={"roster","trade","freeagents","coaches","relocate","brand","standings","playoffs","schedule","training","facilities","league","news","injuries","franchisehub","coach","trophies","history","champions","leaders","stadium","draft"};if(selection==5){brandMascot=Array.IndexOf(Franchise.Mascots,franchise.Club.Mascot);if(brandMascot<0)brandMascot=0;brandPrimary=franchise.Club.Primary;brandSecondary=franchise.Club.Secondary;}Open(destinations[selection]);return;}
  if(screen=="confirm"){Action action=confirmAction;string back=confirmBack;bool yes=selection==1;Open(back);if(yes&&action!=null)action();return;}
  if(selection==rows.Count-1){FrontBack();return;}if(screen=="draft"){if(selection==franchise.Prospects.Count){Confirm("AUTO DRAFT","Your scouts choose all remaining picks.","draft",()=>{franchise.AutoDraft();Open("draft");});return;}ClubPlayer rookie=franchise.Prospects[selection];Confirm("DRAFT "+rookie.Role,rookie.Name+" / "+rookie.OVR+" OVR / $"+rookie.Salary+" salary / 3 years"+franchise.DraftRosterNote(rookie),"draft",()=>{franchise.DraftPlayer(rookie.Id);Open("draft");});return;}if(screen=="stadium"){franchise.SetStadiumPrice(selection<2,selection%2==0?(selection<2?-1:-2):(selection<2?1:2));return;}
  if(screen=="roster"&&selection==FrontPlayers().Count){Open("injuries");return;}if(screen=="teamroster"){selectedPlayer=FrontPlayers()[selection].Id;return;}if(screen=="standings"){viewTeam=franchise.Table()[selection].Team;Open("teamroster");}else if(screen=="roster"){selectedPlayer=FrontPlayers()[selection].Id;Open("player");}
  else if(screen=="trade"){tradePlayer=FrontPlayers()[selection].Id;Open("partners");}
  else if(screen=="player"){ClubPlayer p=SelectedPlayer;if(selection==0)Open("lineup");else if(selection==1)Confirm("RENEW CONTRACT",p.Name+" / "+(3+(p.OVR-70)/3)+" credits / +2 seasons","player",()=>franchise.Renew(p.Id));else if(selection==2)Confirm("RELEASE PLAYER",p.Name+" / must be a reserve / no credit refund","roster",()=>franchise.Release(p.Id));else{tradePlayer=p.Id;Open("partners");}}
  else if(screen=="lineup"){franchise.StartPlayer(selectedPlayer,franchise.EligibleSlots(SelectedPlayer)[selection]);Open("player");}
  else if(screen=="freeagents"){ClubPlayer p=FrontPlayers()[selection];Confirm("SIGN PLAYER",p.Line+" / "+p.SigningCost+" CR / "+p.Salary+" salary / 3 years","freeagents",()=>franchise.Sign(p.Id));}
  else if(screen=="partners"){List<LeagueTeam> partners=franchise.Teams.FindAll(t=>t.Id!=franchise.UserTeam);tradePartner=partners[selection].Id;Open("offers");}
  else if(screen=="offers"){ClubPlayer a=franchise.Players.Find(p=>p.Id==tradePlayer),b=FrontPlayers()[selection];Confirm("EXECUTE TRADE",a.Name+" FOR "+b.Name+" / "+franchise.EvaluateTrade(a,b).Reason,"offers",()=>franchise.Trade(a.Id,b.Id));}
  else if(screen=="coaches"){int type=selection/3,lv=selection%3+1;Confirm("HIRE COACH",new string[]{"OFFENSE","DEFENSE","FITNESS"}[type]+" / TIER "+lv+" / "+(5+lv*5)+" CR","coaches",()=>franchise.Hire(type,lv));}
  else if(screen=="relocate"){if(selection==Franchise.Cities.Length){cityDraft="";Open("cityname");selection=38;return;}int city=selection;Confirm("MOVE YOUR TEAM",Franchise.Cities[city]+" / 15 CR / retain roster and record","relocate",()=>franchise.Relocate(city));}
  else if(screen=="brand"){if(selection==0)brandMascot=(brandMascot+1)%12;else if(selection==1)brandPrimary=(brandPrimary+1)%9;else if(selection==2)brandSecondary=(brandSecondary+1)%9;else{franchise.Edit(brandMascot,brandPrimary,brandSecondary);Open("club");}}
  else if(screen=="league"){int team=selection;Confirm("CHOOSE CLUB",franchise.Teams[team].Name+" / join before opener or between seasons","league",()=>franchise.TakeOver(team));}
  else if(screen=="training"){franchise.Train(selection);}
  else if(screen=="facilities"){int unit=selection;Confirm("UPGRADE FACILITY",rows[unit],"facilities",()=>franchise.Upgrade(unit));}
  else if(screen=="schedule"&&selection==rows.Count-3){LeagueAction();}else if(screen=="schedule"&&selection==rows.Count-2){Confirm("SIM NEXT GAME","Simulates your scheduled game and the other clubs this week.","schedule",()=>{franchise.SimNext();Open("schedule");});}
  else if(screen=="playoffs"&&selection==1)LeagueAction();
 }
 void LeagueAction(){if(franchise.DraftActive){Open("draft");}else if(franchise.Complete){Confirm("START NEXT SEASON","Retirements, contracts and the three-round draft.","club",()=>{franchise.NextSeason();Open("draft");});}else if(franchise.UserGame!=null)StartGame();else{franchise.Advance();Open("club");}}
 void AwardMatch(){if(exhibition){awarded=true;return;}if(awarded||game.Practice||matchFixture<0)return;if(franchise.FinishGame(matchFixture,game.HomeScore,game.AwayScore,game.MatchInjuries,game.SimulatedDrives>0?null:game.Box,game.InjuryReports)){Fixture result=franchise.Games.Find(g=>g.Id==matchFixture);if(result!=null){game.HomeScore=result.Home==franchise.UserTeam?result.HomeScore:result.AwayScore;game.AwayScore=result.Home==franchise.UserTeam?result.AwayScore:result.HomeScore;if(game.Postseason)game.Message="FINAL / "+game.HomeScore+" - "+game.AwayScore;}club.Finish(game.HomeScore.CompareTo(game.AwayScore));awarded=true;matchFixture=-1;}}
 string Clip(string value,int chars){return value.Length>chars?value.Substring(0,chars-3)+"...":value;}
